    #[test]
    fn first_use_imports_bridge_presets() {
        let fixture = Fixture::new();
        let snap = fixture.eq.snapshot();
        assert_eq!(ids(&snap.presets), ["alpha-0001", "beta-0002"]); // the broken one skipped
        assert_eq!(snap.order, ["alpha-0001", "beta-0002"]);
        assert!(snap.presets.iter().all(|preset| preset.source == "bridge"));
        assert_eq!(snap.active.as_deref(), Some("beta-0002")); // the other application's pick carries over
        assert!(!snap.enabled); // but nothing is switched on
        assert!(fixture.state.exists());
        assert_eq!(fs::metadata(&fixture.state).unwrap().permissions().mode() & 0o777, 0o600);
        assert_eq!(fixture.eq.import_bridge_presets(), Ok(0));
        bridge_file(
            &fixture.bridge,
            json!([bridge_preset("gamma-0004", "Gamma", -1.0, json!([]))]),
            Some("gamma-0004"),
        );
        assert_eq!(fixture.eq.import_bridge_presets(), Ok(1));
        assert_eq!(fixture.eq.active().unwrap().id, "beta-0002"); // a later import never moves the pick
        assert_eq!(fixture.eq.snapshot().order.last().unwrap(), "gamma-0004");
        // the other application's file is read only
        let theirs: Value = serde_json::from_str(&fs::read_to_string(&fixture.bridge).unwrap()).unwrap();
        assert_eq!(theirs["presets"][0]["id"], "gamma-0004");
    }

    #[test]
    fn presets_persist() {
        let fixture = Fixture::new();
        let preset = fixture.eq.add_preset("  My IEMs  ", APO_TEXT, "pasted").unwrap();
        assert!(preset.id.starts_with("my-iems-"));
        assert_eq!(
            (preset.name.as_str(), preset.preamp, preset.filters.len(), preset.source.as_str()),
            ("My IEMs", -6.2, 4, "pasted")
        );
        fixture.eq.rename_preset(&preset.id, "Renamed").unwrap();
        fixture.eq.move_preset(&preset.id, 0).unwrap();
        fixture.eq.set_active(Some(&preset.id)).unwrap();
        fixture.eq.set_enabled(true).unwrap();
        let again = fixture.make(); // a fresh instance on the same file
        let snap = again.snapshot();
        assert_eq!(snap.order[0], preset.id);
        assert_eq!(snap.presets[0].name, "Renamed");
        assert_eq!(snap.presets[0].filters, preset.filters);
        assert_eq!(snap.active.as_ref(), Some(&preset.id));
        assert!(snap.enabled);
        assert_eq!(again.move_preset(&preset.id, 99).unwrap().last(), Some(&preset.id)); // clamped
        again.delete_preset(&preset.id).unwrap();
        assert_eq!(again.active(), None);
        assert!(again.enabled());
        assert_eq!(again.presets().len(), 2);
        assert_eq!(again.set_active(Some("nope")), Err(EqError::Other("no such preset".into())));
        assert_eq!(again.rename_preset("alpha-0001", "   "), Err(EqError::Other("the name is empty".into())));
        assert_eq!(again.add_preset("bad", "garbage", "pasted").unwrap_err().line(), Some(1));
        assert_eq!(again.presets().len(), 2);
        assert_eq!(fixture.eq.reload().order, again.snapshot().order);
    }

