    // --- the sink (stubbed)

    #[test]
    fn apply_preset_and_flat() {
        let fixture = Fixture::new();
        let eq = &fixture.eq;
        eq.set_active(Some("alpha-0001")).unwrap();
        eq.set_enabled(true).unwrap();
        let values = eq.apply(0.0).unwrap();
        assert_eq!(values.len(), 2 + 2 * 32 * 3);
        assert!(values.iter().all(|(name, _)| name.starts_with("eq"))); // never the matrix / preamp
        assert!(almost(value(&values, "eqgain_l:Mult"), 10f64.powf(-5.7 / 20.0)));
        assert_eq!(value(&values, "eqgain_r:Mult"), value(&values, "eqgain_l:Mult"));
        let slot = |values: &Controls, slot: &str| {
            ["Freq", "Gain", "Q"].map(|control| value(values, &format!("{slot}:{control}")))
        };
        assert_eq!(slot(&values, "eq_l_pk1"), [1000.0, -2.0, 1.0]);
        assert_eq!(slot(&values, "eq_r_lsc1")[..2], [100.0, 2.0]);
        assert_eq!(slot(&values, "eq_l_pk2"), [1000.0, 0.0, 0.707]);
        assert_eq!(fixture.applied.lock().unwrap().last(), Some(&values));
        let live = eq.live_state().unwrap();
        assert_eq!((live.enabled_in_sink, live.bands), (true, 2));
        assert!(almost(live.gain_db.unwrap(), -5.7));
        // Sound Check trim rides on the gain stage only
        let values = eq.apply(-2.0).unwrap();
        assert!(almost(value(&values, "eqgain_l:Mult"), 10f64.powf(-7.7 / 20.0)));
        assert_eq!(value(&values, "eq_l_pk1:Gain"), -2.0);
        // disabled: flat, the trim alone (how the live round trip restores the other application's gain)
        eq.set_enabled(false).unwrap();
        let values = eq.apply(-8.3).unwrap();
        assert!(values.iter().filter(|(name, _)| name.ends_with(":Gain")).all(|(_, gain)| gain == 0.0));
        assert!(almost(value(&values, "eqgain_l:Mult"), 10f64.powf(-8.3 / 20.0)));
        let live = eq.live_state().unwrap();
        assert_eq!((live.enabled_in_sink, live.bands), (false, 0));
        assert!(almost(live.gain_db.unwrap(), -8.3));
        let audit = fixture.audit();
        assert_eq!(audit.len(), 3);
        assert!(audit[0].contains("preset=alpha-0001 preamp=-5.70 filters=2 trim=+0.00 gain=-5.70 dB"), "{}", audit[0]);
        assert!(audit[2].contains("eq applied flat trim=-8.30 gain=-8.30 dB enabled=False"), "{}", audit[2]);
        assert_eq!(eq.apply(f64::NAN), Err(EqError::Other("trim out of range".into())));
    }

