    /// In Python the module's functions (`eq.presets()`, `eq.apply()`, ...) were shorthands for
    /// one process-wide `Equalizer`; here the application shares one, and every holder works on
    /// the same state.
    #[test]
    fn module_api_uses_the_shared_manager() {
        let fixture = Fixture::new();
        let eq = fixture.eq.clone();
        assert_eq!(ids(&eq.presets()), ["alpha-0001", "beta-0002"]);
        assert_eq!(eq.active().unwrap().id, "beta-0002");
        assert!(!eq.enabled());
        eq.set_enabled(true).unwrap();
        assert!(almost(value(&eq.apply(0.0).unwrap(), "eqgain_l:Mult"), 10f64.powf(-3.0 / 20.0)));
        assert_eq!(eq.live_state().unwrap().bands, 1);
        eq.set_active(None).unwrap();
        assert_eq!(eq.active(), None);
        assert_eq!(eq.import_bridge_presets(), Ok(0));
        assert_eq!(eq.move_preset("alpha-0001", 1).unwrap(), ["beta-0002", "alpha-0001"]);
        eq.delete_preset(&eq.add_preset("Tmp", APO_TEXT, "pasted").unwrap().id).unwrap();
        assert_eq!(eq.snapshot().presets.len(), 2);
        // the other holder saw all of it
        assert!(fixture.eq.enabled() && fixture.eq.active().is_none());
        assert_eq!(fixture.eq.snapshot().order, ["beta-0002", "alpha-0001"]);
    }

    // --- what the port adds

    /// The engine side of the page's fake mode: an equalizer in memory with sample presets and
    /// a stand-in sink that remembers what was applied, as the Qt tests drove it.
    #[test]
    fn an_equalizer_in_memory_serves_the_page_s_fake_mode() {
        let applied = Applied::default();
        let eq = remembering(&applied);
        assert_eq!((eq.path(), eq.bridge_path()), (None, None));
        let added: Vec<Preset> =
            SAMPLE_PRESETS.iter().map(|(name, text)| eq.add_preset(name, text, "sample").unwrap()).collect();
        eq.set_active(Some(&added[0].id)).unwrap();

        // the page shows the fake presets
        let snap = eq.snapshot();
        assert_eq!(
            snap.presets.iter().map(|preset| preset.name.as_str()).collect::<Vec<_>>(),
            ["Reference", "Warm", "Bright"]
        );
        assert!(snap.presets.iter().all(|preset| preset.source == "sample") && !snap.bridge_imported);
        assert_eq!((eq.active().unwrap().name.as_str(), eq.enabled()), ("Reference", false));
        assert_eq!(curve(eq.active().as_ref(), CURVE_POINTS).len(), 200);
        let live = eq.live_state().unwrap();
        assert_eq!((live.enabled_in_sink, live.bands), (false, 0));
        assert!(almost(live.gain_db.unwrap(), -8.3));
        // switch on, activate another, switch off
        eq.set_enabled(true).unwrap();
        eq.apply(0.0).unwrap();
        assert_eq!(eq.live_state().unwrap().bands, 3);
        eq.set_active(Some(&added[2].id)).unwrap();
        eq.apply(0.0).unwrap();
        assert_eq!(eq.live_state().unwrap().bands, 5);
        eq.set_enabled(false).unwrap();
        eq.apply(0.0).unwrap();
        assert_eq!(eq.live_state().unwrap(), LiveState { enabled_in_sink: false, bands: 0, gain_db: Some(0.0) });
        // the paste sheet: an error on line 4, then a preview and a fourth card
        let pasted =
            "Preamp: -6 dB\nFilter 1: ON PK Fc 1000 Hz Gain 6 dB Q 1\nFilter 2: OFF PK Fc 2000 Hz Gain -3 dB Q 2\n";
        let error = parse(&format!("{pasted}bogus")).unwrap_err();
        assert_eq!((error.line(), error.to_string().contains("line 4")), (Some(4), true));
        let (preamp, filters) = parse(pasted).unwrap();
        assert_eq!((filters.len(), preamp), (1, -6.0));
        let preview = curve(Some(&Preset::of(preamp, filters)), CURVE_POINTS);
        let top = preview.iter().map(|point| point[1]).fold(f64::MIN, f64::max);
        assert_eq!(preview.len(), 200);
        assert!(top.abs() <= 0.05); // +6 dB peak on a -6 dB preamp
        let pasted = eq.add_preset("Pasted", pasted, "pasted").unwrap();
        assert_eq!((eq.presets().len(), eq.presets()[3].name.as_str()), (4, "Pasted"));
        assert_eq!(eq.preset(&pasted.id).unwrap().text.as_deref(), Some(pasted.text.as_deref().unwrap()));
        // the card menu: rename, move, delete; importing finds nothing
        assert_eq!(eq.rename_preset(&added[1].id, "Warmer").unwrap().name, "Warmer");
        assert_eq!(eq.move_preset(&added[1].id, 0).unwrap()[0], added[1].id);
        eq.delete_preset(&pasted.id).unwrap();
        assert_eq!((eq.presets().len(), eq.import_bridge_presets()), (3, Ok(0)));
        // deleting the active preset of an enabled EQ: the caller applies, and the sink goes flat
        eq.set_enabled(true).unwrap();
        eq.delete_preset(&added[2].id).unwrap();
        assert_eq!(eq.active(), None);
        eq.apply(0.0).unwrap();
        assert_eq!(eq.live_state().unwrap().bands, 0);
        assert_eq!(
            curve(eq.active().as_ref(), CURVE_POINTS).iter().map(|point| point[1]).collect::<Vec<_>>(),
            [0.0; 200]
        );
        assert_eq!(eq.reload().presets.len(), 2); // a state in memory stays
        assert_eq!(applied.lock().unwrap().len(), 4);
    }

    /// The live round trip of the Python notes, on the stand-in programs: apply a preset, read it
    /// back, restore the gain that was found.
    #[test]
    fn the_real_sink_takes_only_the_eq_controls() {
        let scratch = Scratch::new();
        let (sink, downmix) = (&scratch.sink, &scratch.downmix);
        let eq = Equalizer::new(downmix.clone());
        assert_eq!(eq.path(), Some(scratch.config.state_dir.join("eq.json").as_path()));
        assert_eq!(eq.bridge_path(), Some(bridge_state_path(&scratch.config).as_path()));
        let before = downmix.live_controls().unwrap();
        sink.take_calls();
        assert_eq!(eq.snapshot().presets, []); // no file of the other application in the scratch home
        assert!(!eq.snapshot().bridge_imported && eq.path().unwrap().exists());

        let preset = eq.add_preset("Reference", APO_TEXT, "pasted").unwrap();
        eq.set_active(Some(&preset.id)).unwrap();
        eq.set_enabled(true).unwrap();
        assert!(sink.calls.lock().unwrap().is_empty()); // nothing reaches the sink before apply
        let values = eq.apply(0.0).unwrap();
        let line = line!() - 1;
        let cases = &reference()["eq_controls"];
        assert_controls(&values, &control_list(&cases[0]["controls"]));
        let calls = sink.calls.lock().unwrap().clone();
        assert_eq!(calls[0], (words(&["pw-cli", "ls", "Node"]), Some(std::time::Duration::from_secs(10))));
        assert_eq!(calls[1], (words(&["pw-dump"]), None));
        assert_eq!(calls[2], (words(&["pw-cli", "set-param", "38", "Props", text(&cases[0]["argument"])]), None));
        assert_eq!(sink.take_calls().len(), 3);
        let live = eq.live_state().unwrap();
        assert_eq!((live.enabled_in_sink, live.bands), (true, 4));
        assert!((live.gain_db.unwrap() - -6.2).abs() < 1e-5);

        // disabled, with the gain stage the other application had: flat again
        eq.set_enabled(false).unwrap();
        sink.take_calls();
        eq.apply(-8.3).unwrap();
        let flat = words(&["pw-cli", "set-param", "38", "Props", text(&cases[3]["argument"])]);
        assert_eq!(sink.take_calls(), [words(&["pw-cli", "ls", "Node"]), flat]); // the node is remembered
        let live = eq.live_state().unwrap();
        assert_eq!((live.enabled_in_sink, live.bands), (false, 0));
        assert!((live.gain_db.unwrap() - -8.3).abs() < 1e-5);
        // no control of the matrix or the preamp differs from the state found
        let after = downmix.live_controls().unwrap();
        for (name, was) in before.iter().filter(|(name, _)| !name.starts_with("eq")) {
            assert_eq!(after.get(name), Some(was), "{name}");
        }
        assert_eq!(before.iter().filter(|(name, _)| !name.starts_with("eq")).count(), 26);

        // both applies are in the sink's audit log, as this module's
        let audit = scratch.audit_lines();
        assert_eq!(audit.len(), 2);
        let applied =
            format!("eq applied preset={} preamp=-6.20 filters=4 trim=+0.00 gain=-6.20 dB enabled=True", preset.id);
        assert!(audit[0].ends_with(&applied), "{}", audit[0]);
        assert!(audit[1].ends_with("eq applied flat trim=-8.30 gain=-8.30 dB enabled=False"), "{}", audit[1]);
        let caller = Regex::new(r"\] eq\.rs:(\d+) eq applied ").unwrap();
        let logged: usize = caller.captures(&audit[0]).unwrap()[1].parse().unwrap();
        assert!(logged < line as usize, "the line of the apply in this module, not of the test");

        // what the sink refuses is reported and logged
        sink.fail(
            "set-param",
            Ok(downmix::Output {
                status: Some(0),
                stdout: "Error: \"set-param: unknown global 38\"\n".into(),
                stderr: String::new(),
            }),
        );
        let error = eq.apply(0.0).unwrap_err();
        assert_eq!(
            error,
            EqError::Sink(
                "could not set the sink's EQ: could not set the controls of node 38 (atmos_916_downmix)".into()
            )
        );
        assert!(
            scratch.audit_lines()[2]
                .ends_with("eq FAILED flat trim=+0.00: could not set the controls of node 38 (atmos_916_downmix)")
        );
        sink.faults.lock().unwrap().clear();
        sink.fail("pw-dump", Err(downmix::RunError::NotFound));
        assert_eq!(
            eq.apply(0.0).unwrap_err().to_string(),
            "could not set the sink's EQ: pw-dump failed (FileNotFoundError)"
        );
        sink.fail("enum-params", Err(downmix::RunError::Timeout));
        assert_eq!(eq.live_state(), Err(EqError::Sink("pw-cli failed (TimeoutExpired)".into())));
    }

    #[test]
    fn stand_ins_replace_the_sink_one_by_one() {
        let scratch = Scratch::new();
        let applied = Applied::default();
        let sent = applied.clone();
        let refusing = Equalizer::new(scratch.downmix.clone()).with_apply_fn(move |values: &Controls| {
            sent.lock().unwrap().push(values.clone());
            Err(EqError::Sink("the stand-in refuses".into()))
        });
        assert_eq!(refusing.apply(0.0), Err(EqError::Sink("the stand-in refuses".into())));
        assert_eq!(applied.lock().unwrap().len(), 1);
        assert_eq!(refusing.live_state().unwrap().bands, 0); // the live controls still come from the sink
        assert_eq!(scratch.sink.programs(), ["pw-cli ls", "pw-cli enum-params"]);
        assert!(scratch.audit_lines().is_empty()); // a stand-in's applies are not the sink's

        let reading =
            Equalizer::new(scratch.downmix.clone()).with_live_fn(|| Err(DownmixError::Failed("no reading".into())));
        assert_eq!(reading.live_state(), Err(EqError::Sink("no reading".into())));
        reading.apply(0.0).unwrap(); // the real sink
        assert_eq!(scratch.audit_lines().len(), 1);
        let silent = Equalizer::detached(
            |_: &Controls| Ok(()),
            || Ok([("eqgain_l:Mult", 0.0), ("other:Gain", 3.0)].into_iter().collect()),
        );
        assert_eq!(silent.live_state(), Ok(LiveState { enabled_in_sink: false, bands: 0, gain_db: Some(-120.0) }));
        assert_eq!(
            idle().live_state().unwrap().to_json(),
            json!({"enabled_in_sink": false, "bands": 0, "gain_db": null})
        );
    }

