    #[test]
    fn curves_are_python_s() {
        // the same bits where the math library is the reference's; a billionth of a dB elsewhere
        let near = |got: f64, want: f64| got == want || (got - want).abs() <= 1e-9;
        for case in list(&reference()["curves"]) {
            let name = text(&case["name"]);
            let (preamp, filters) = parse(text(&case["text"])).unwrap();
            let preset = Preset::of(preamp, filters);
            let freqs: Vec<f64> = list(&case["freqs"]).iter().map(float).collect();
            let got = response(Some(&preset), &freqs);
            for (got, want) in got.iter().zip(list(&case["response"])) {
                assert!(near(*got, float(want)), "{name}: {got:?} != {want}");
            }
            let spark = response(Some(&preset), &default_freqs(64));
            assert_eq!(spark.len(), 64);
            for (got, want) in spark.iter().zip(list(&case["spark"])) {
                assert!(near(*got, float(want)), "{name}: {got:?} != {want}");
            }
            for (points, n) in [("curve5", 5), ("curve", CURVE_POINTS)] {
                let Some(want) = case.get(points) else { continue };
                let got = curve(Some(&preset), n);
                assert_eq!(got.len(), list(want).len());
                for (got, want) in got.iter().zip(list(want)) {
                    assert!(
                        near(got[0], float(&want[0])) && near(got[1], float(&want[1])),
                        "{name}: {got:?} != {want}"
                    );
                }
            }
            if name == "minus zero" {
                assert_eq!((preset.preamp.to_bits(), got[0].to_bits()), ((-0.0f64).to_bits(), 0.0f64.to_bits()));
            }
        }
        for (n, want) in reference()["default_freqs"].as_object().unwrap() {
            let got = default_freqs(n.parse().unwrap());
            assert_eq!(got.len(), list(want).len(), "{n}");
            assert!(got.iter().zip(list(want)).all(|(got, want)| close(*got, float(want))), "{n}");
        }
        for case in list(&reference()["biquad"]) {
            let (freq, gain, q) = (float(&case["freq"]), float(&case["gain"]), float(&case["q"]));
            let got = biquad_coefficients(text(&case["kind"]), freq, gain, q, SAMPLE_RATE).unwrap();
            for (got, want) in got.iter().zip(list(&case["coefficients"])) {
                assert!(close(*got, float(want)), "{case}: {got:?}");
            }
        }
        // ties go to the even digit, and a rounded-away negative keeps its sign
        assert_eq!((round3(0.1875), round3(0.0625), round3(1.23456)), (0.188, 0.062, 1.235));
        assert_eq!(round3(-0.0004).to_bits(), (-0.0f64).to_bits());
        assert!(round3(f64::NAN).is_nan() && round3(f64::INFINITY).is_infinite());
    }

    #[test]
    fn names_and_texts_are_python_s() {
        for case in list(&reference()["slug"]) {
            assert_eq!(slug(text(&case[0])), text(&case[1]), "{}", case[0]);
        }
        for case in list(&reference()["preset_text"]) {
            let (preamp, filters) = parse(text(&case["text"])).unwrap();
            assert_eq!(preset_text(&Preset::of(preamp, filters)), text(&case["written"]));
        }
        let token = token_hex();
        assert!(token.len() == 4 && token.chars().all(|c| c.is_ascii_hexdigit() && !c.is_ascii_uppercase()), "{token}");
        // names: blanks around them go, 80 characters stay, an empty one is "Preset"
        let eq = idle();
        let long = eq.add_preset(&format!("  {}  ", "n".repeat(100)), "", "pasted").unwrap();
        assert_eq!((long.name.len(), long.id.len()), (80, 40 + 5));
        let unnamed = eq.add_preset(" \t ", "Preamp: -1 dB\n\n", "pasted").unwrap();
        assert_eq!(
            (unnamed.name.as_str(), &unnamed.id[..7], unnamed.text.as_deref()),
            ("Preset", "preset-", Some("Preamp: -1 dB"))
        );
        assert_eq!(eq.rename_preset(&unnamed.id, &format!(" {} ", "r".repeat(90))).unwrap().name, "r".repeat(80));
        assert_eq!(eq.rename_preset("", "x"), Err(EqError::Other("no such preset".into())));
        assert_eq!(eq.delete_preset("nope"), Err(EqError::Other("no such preset".into())));
        assert_eq!(eq.move_preset("nope", 0), Err(EqError::Other("no such preset".into())));
        assert_eq!(eq.move_preset(&unnamed.id, -5).unwrap(), [unnamed.id.clone(), long.id.clone()]);
        assert_eq!(eq.set_active(Some("")).unwrap().active, None);
        for trim in [-120.5, 40.5, f64::INFINITY] {
            assert_eq!(eq.apply(trim), Err(EqError::Other("trim out of range".into())));
        }
        assert!(eq.apply(-120.0).is_ok() && eq.apply(40.0).is_ok());
    }

